#include "fixes/custom_map_asset_isolation/PlayerStoredProgressSnapshot.h"
#include <cstdio>
#include <cstring>
namespace progress=dluma::fixes::custom_map_asset_isolation::player_stored_progress;
namespace {
#define CHECK(x)do{if(!(x)){std::printf("FAIL %d: %s\n",__LINE__,#x);return false;}}while(0)
struct Fake {unsigned char state[1200]={},context[progress::kContextBytes]={};std::uint64_t revision=1;unsigned calls=0;bool active=false,exclusive=true,mutate=false;Fake(){std::uintptr_t vt=0x117E2FF8,ctx=reinterpret_cast<std::uintptr_t>(context);std::memcpy(state,&vt,8);std::memcpy(state+0x468,&ctx,8);}};
bool Read(void*,std::uintptr_t p,void* out,std::size_t n)noexcept{if(!p&&n)return false;std::memcpy(out,reinterpret_cast<const void*>(p),n);return true;}
bool Fence(void* user,progress::Fence* out)noexcept{auto& f=*static_cast<Fake*>(user);*out={reinterpret_cast<std::uintptr_t>(f.state),f.active?1U:0U,0,7,f.revision,GetCurrentThreadId(),f.exclusive};return true;}
bool Serialize(void* user,progress::Section section,std::uintptr_t,progress::Stream* stream)noexcept{auto& f=*static_cast<Fake*>(user);++f.calls;unsigned value=100+static_cast<unsigned>(section);if(f.mutate)++f.revision;using Fn=std::uint64_t(__fastcall*)(progress::Stream*,const void*,std::uint64_t);return reinterpret_cast<Fn>(stream->vtable[7])(stream,&value,sizeof(value))==sizeof(value);}
progress::Reader Reader(Fake& f){return {0x10000000,Read,Fence,Serialize,&f,1<<20,true};}
bool Capture(Fake& f,progress::Snapshot& out){return progress::Capture(Reader(f),reinterpret_cast<std::uintptr_t>(f.state),7,&out);}
bool ActualStoredSections(){Fake f;progress::Snapshot a={},b={};CHECK(Capture(f,a));CHECK(a.stored_sections_complete&&!a.complete_player_preservation);CHECK(f.calls==8);CHECK(Capture(f,b));CHECK(progress::Equal(a,b));return true;}
bool CachedAbsenceNotPlayerAbsence(){Fake f;std::memset(f.state+0x468,0,8);progress::Snapshot out={};CHECK(Capture(f,out));CHECK(out.cached_context_absent&&!out.stored_sections_complete&&!out.complete_player_preservation);CHECK(f.calls==0);return true;}
bool WalletAndEquipmentAreSemantic(){Fake f;progress::Snapshot a={},b={};CHECK(Capture(f,a));f.context[3480]=23;CHECK(Capture(f,b));CHECK(!progress::Equal(a,b));CHECK(std::memcmp(a.sections[static_cast<unsigned>(progress::Section::Wallet)].sha256,b.sections[static_cast<unsigned>(progress::Section::Wallet)].sha256,32)!=0);return true;}
bool InvalidHeaderBlocksNativeCalls(){Fake f;std::uint32_t count=1;std::memcpy(f.context+32,&count,4);progress::Snapshot out={};CHECK(!Capture(f,out));CHECK(out.failure==progress::Failure::InvalidHeader&&f.calls==0);return true;}
bool QuiescenceAndSessionRequired(){Fake f;progress::Snapshot out={};f.active=true;CHECK(!Capture(f,out)&&out.failure==progress::Failure::ActiveSession);f.active=false;f.exclusive=false;CHECK(!Capture(f,out)&&out.failure==progress::Failure::QuiescenceUnavailable);CHECK(f.calls==0);return true;}
bool WriterFenceChangeRejected(){Fake f;f.mutate=true;progress::Snapshot out={};CHECK(!Capture(f,out));CHECK(out.failure==progress::Failure::StateChanged&&!out.stored_sections_complete);return true;}
bool BoundedStreamAndUnsupportedOperation(){progress::Stream s={};progress::Digest d={};progress::InitializeStream(&s,2,Read,nullptr);std::uint32_t n=3;CHECK(progress::WriteStream(&s,&n,4)==0);CHECK(!progress::FinishStream(&s,&d));CHECK(s.failure==progress::Failure::OutputLimit);progress::InitializeStream(&s,20,Read,nullptr);using Fn=std::uint64_t(__fastcall*)(progress::Stream*);reinterpret_cast<Fn>(s.vtable[4])(&s);CHECK(!progress::FinishStream(&s,&d));CHECK(s.failure==progress::Failure::UnsupportedStreamOperation);return true;}
bool DirectSectionsDoNotInvokeUnqualifiedDescriptors(){Fake f;auto r=Reader(f);r.serialize_section=nullptr;progress::Snapshot a={},b={};CHECK(progress::CaptureDirect(r,reinterpret_cast<std::uintptr_t>(f.state),7,&a));CHECK(f.calls==0&&!a.stored_sections_complete&&!a.complete_player_preservation);CHECK(a.available_section_mask==((1U<<1)|(1U<<2)|(1U<<3)|(1U<<4)|(1U<<8)));CHECK(progress::CaptureDirect(r,reinterpret_cast<std::uintptr_t>(f.state),7,&b)&&progress::Equal(a,b));f.context[3480]=12;CHECK(progress::CaptureDirect(r,reinterpret_cast<std::uintptr_t>(f.state),7,&b)&&!progress::Equal(a,b));return true;}
}
int main(){bool(*tests[])()={ActualStoredSections,CachedAbsenceNotPlayerAbsence,WalletAndEquipmentAreSemantic,InvalidHeaderBlocksNativeCalls,QuiescenceAndSessionRequired,WriterFenceChangeRejected,BoundedStreamAndUnsupportedOperation,DirectSectionsDoNotInvokeUnqualifiedDescriptors};for(unsigned i=0;i<sizeof(tests)/sizeof(tests[0]);++i){if(!tests[i]())return 1;std::printf("PASS stored_progress_%u\n",i);}return 0;}
